BEGIN;
CREATE TABLE IF NOT EXISTS companies (id serial PRIMARY KEY, name text NOT NULL, phone text NOT NULL DEFAULT '', email text NOT NULL DEFAULT '', address text NOT NULL DEFAULT '', logo_url text NOT NULL DEFAULT '', currency text NOT NULL DEFAULT 'MMK', timezone text NOT NULL DEFAULT 'Asia/Yangon', ticket_footer text NOT NULL DEFAULT 'Please arrive 30 minutes before departure.');
CREATE TABLE IF NOT EXISTS regions (id serial PRIMARY KEY, company_id int NOT NULL REFERENCES companies, name text NOT NULL);
CREATE TABLE IF NOT EXISTS cities (id serial PRIMARY KEY, region_id int NOT NULL REFERENCES regions, name text NOT NULL);
CREATE TABLE IF NOT EXISTS branches (id serial PRIMARY KEY, city_id int NOT NULL REFERENCES cities, name text NOT NULL, code text UNIQUE NOT NULL, address text NOT NULL DEFAULT '', phone text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','inactive')));
CREATE TABLE IF NOT EXISTS counters (id serial PRIMARY KEY, branch_id int NOT NULL REFERENCES branches, name text NOT NULL, UNIQUE(id,branch_id));
CREATE TABLE IF NOT EXISTS roles (name text PRIMARY KEY);
CREATE TABLE IF NOT EXISTS permissions (key text PRIMARY KEY);
CREATE TABLE IF NOT EXISTS role_permissions (role text REFERENCES roles, permission text REFERENCES permissions, PRIMARY KEY(role,permission));
CREATE TABLE IF NOT EXISTS users (id serial PRIMARY KEY, username text UNIQUE NOT NULL, name text NOT NULL, password_hash text NOT NULL, role text NOT NULL REFERENCES roles, company_id int NOT NULL REFERENCES companies, region_id int REFERENCES regions, branch_id int REFERENCES branches, counter_id int, status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','inactive')), FOREIGN KEY(counter_id,branch_id) REFERENCES counters(id,branch_id));
CREATE TABLE IF NOT EXISTS buses (id serial PRIMARY KEY, branch_id int NOT NULL REFERENCES branches, code text UNIQUE NOT NULL, plate_number text UNIQUE NOT NULL, model text NOT NULL, status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','maintenance','inactive')));
CREATE TABLE IF NOT EXISTS seats (id serial PRIMARY KEY, bus_id int NOT NULL REFERENCES buses, seat_number text NOT NULL, row_number int NOT NULL CHECK(row_number>0), column_number int NOT NULL CHECK(column_number>0), seat_type text NOT NULL DEFAULT 'normal', UNIQUE(bus_id,seat_number));
CREATE TABLE IF NOT EXISTS routes (id serial PRIMARY KEY, company_id int NOT NULL REFERENCES companies, code text UNIQUE NOT NULL, origin text NOT NULL, destination text NOT NULL, duration_minutes int NOT NULL CHECK(duration_minutes>0), distance_km int NOT NULL CHECK(distance_km>0));
CREATE TABLE IF NOT EXISTS route_stops (id serial PRIMARY KEY, route_id int NOT NULL REFERENCES routes, name text NOT NULL, stop_order int NOT NULL, latitude double precision NOT NULL CHECK(latitude BETWEEN -90 AND 90), longitude double precision NOT NULL CHECK(longitude BETWEEN -180 AND 180), UNIQUE(route_id,stop_order));
CREATE TABLE IF NOT EXISTS schedules (id serial PRIMARY KEY, route_id int NOT NULL REFERENCES routes, bus_id int NOT NULL REFERENCES buses, departure_time time NOT NULL, days_of_week int[] NOT NULL DEFAULT '{0,1,2,3,4,5,6}');
CREATE TABLE IF NOT EXISTS trips (id serial PRIMARY KEY, schedule_id int REFERENCES schedules, route_id int NOT NULL REFERENCES routes, bus_id int NOT NULL REFERENCES buses, origin_branch_id int NOT NULL REFERENCES branches, destination_branch_id int NOT NULL REFERENCES branches, driver_id int REFERENCES users, conductor_id int REFERENCES users, departure_at timestamptz NOT NULL, arrival_at timestamptz NOT NULL, fare int NOT NULL CHECK(fare>0), status text NOT NULL DEFAULT 'scheduled' CHECK(status IN ('scheduled','boarding','departed','in_transit','arrived','completed','delayed','cancelled')), CHECK(arrival_at>departure_at), UNIQUE(bus_id,departure_at));
CREATE TABLE IF NOT EXISTS bookings (id serial PRIMARY KEY, reference text NOT NULL UNIQUE, trip_id int NOT NULL REFERENCES trips, created_by int NOT NULL REFERENCES users, branch_id int NOT NULL REFERENCES branches, counter_id int REFERENCES counters, source text NOT NULL CHECK(source IN ('online','counter','agent','admin')), status text NOT NULL CHECK(status IN ('held','confirmed','cancelled','expired')), total int NOT NULL CHECK(total>0), held_until timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS passengers (id serial PRIMARY KEY, name text NOT NULL, phone text NOT NULL);
CREATE TABLE IF NOT EXISTS booking_passengers (id serial PRIMARY KEY, booking_id int NOT NULL REFERENCES bookings, passenger_id int NOT NULL REFERENCES passengers, seat_id int NOT NULL REFERENCES seats, boarding_status text NOT NULL DEFAULT 'not_boarded' CHECK(boarding_status IN ('not_boarded','boarded','no_show')), UNIQUE(booking_id,seat_id));
CREATE TABLE IF NOT EXISTS trip_seats (trip_id int NOT NULL REFERENCES trips, seat_id int NOT NULL REFERENCES seats, status text NOT NULL DEFAULT 'available' CHECK(status IN ('available','held','booked','blocked')), booking_id int REFERENCES bookings, held_until timestamptz, PRIMARY KEY(trip_id,seat_id));
CREATE TABLE IF NOT EXISTS payments (id serial PRIMARY KEY, booking_id int NOT NULL UNIQUE REFERENCES bookings, reference text UNIQUE NOT NULL, method text NOT NULL CHECK(method IN ('cash','bank_transfer','mobile_wallet')), amount int NOT NULL CHECK(amount>0), processed_by int NOT NULL REFERENCES users, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS tickets (id serial PRIMARY KEY, booking_id int NOT NULL UNIQUE REFERENCES bookings, number text UNIQUE NOT NULL, status text NOT NULL DEFAULT 'valid' CHECK(status IN ('valid','cancelled')), issued_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS refunds (id serial PRIMARY KEY, booking_id int NOT NULL UNIQUE REFERENCES bookings, payment_id int NOT NULL REFERENCES payments, amount int NOT NULL CHECK(amount>=0), reason text NOT NULL, status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','completed')), processed_by int REFERENCES users, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS commissions (id serial PRIMARY KEY, booking_id int NOT NULL UNIQUE REFERENCES bookings, agent_id int NOT NULL REFERENCES users, amount int NOT NULL CHECK(amount>=0), status text NOT NULL DEFAULT 'earned' CHECK(status IN ('earned','reversed')));
CREATE TABLE IF NOT EXISTS notifications (id serial PRIMARY KEY, user_id int NOT NULL REFERENCES users, message text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_logs (id bigserial PRIMARY KEY, user_id int REFERENCES users, action text NOT NULL, entity text NOT NULL, entity_id int, details jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE OR REPLACE FUNCTION prevent_audit_edit() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Audit records are append-only'; END $$;
DROP TRIGGER IF EXISTS audit_immutable ON audit_logs;
CREATE TRIGGER audit_immutable BEFORE UPDATE OR DELETE ON audit_logs FOR EACH ROW EXECUTE FUNCTION prevent_audit_edit();
CREATE INDEX IF NOT EXISTS trips_departure ON trips(departure_at);
CREATE INDEX IF NOT EXISTS bookings_owner ON bookings(created_by,created_at);
CREATE INDEX IF NOT EXISTS bookings_branch ON bookings(branch_id,created_at);
CREATE INDEX IF NOT EXISTS holds_expiry ON trip_seats(held_until) WHERE status='held';
COMMIT;
